scene.background = new THREE.Color('#10141f');
camera.position.set(4, 3, 6);
controls.target.set(0, 0, 0);

// A soft studio light and a directional key light.
scene.add(new THREE.HemisphereLight('#cbdcff', '#45415d', 2));
const light = new THREE.DirectionalLight('#ffffff', 3);
light.position.set(3, 5, 4);
scene.add(light);

const grid = new THREE.GridHelper(14, 28, '#30374d', '#202738');
grid.position.y = -1.05;
scene.add(grid);

grid.visible = false;
const planet = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.1, 2),
  new THREE.MeshStandardMaterial({ color: '#b49aff', roughness: 0.75, flatShading: true })
);
scene.add(planet);
const orbit = new THREE.Group();
scene.add(orbit);
const moon = new THREE.Mesh(new THREE.IcosahedronGeometry(0.25, 1), new THREE.MeshStandardMaterial({ color: '#a9e8ce', flatShading: true }));
moon.position.x = 2.2;
orbit.add(moon);

const ring = new THREE.Mesh(
  new THREE.TorusGeometry(1.65, 0.045, 8, 96),
  new THREE.MeshStandardMaterial({ color: '#f2c99b', roughness: 0.4 })
);
ring.rotation.x = Math.PI / 2.5;
ring.rotation.y = -0.3;
scene.add(ring);

const stars = new THREE.BufferGeometry();
const starPositions = [];
for (let i = 0; i < 300; i++) {
  const angle = i * 2.39996;
  const y = 1 - 2 * i / 300;
  const r = Math.sqrt(1 - y * y);
  starPositions.push(Math.cos(angle) * r * 12, y * 12, Math.sin(angle) * r * 12);
}
stars.setAttribute('position', new THREE.Float32BufferAttribute(starPositions, 3));
const starField = new THREE.Points(stars, new THREE.PointsMaterial({ color: '#b9c9e9', size: 0.045 }));
scene.add(starField);

starField.visible = false;
onFrame(({ delta }) => { orbit.rotation.y += delta * 0.4; });

